-- =====================================================================
-- new-game-log 初期データ投入 SQL (seed-initial-data.sql)
-- 生成元: src/data/seedData.ts の INITIAL_SEED_RECORDS (全259件) と
-- src/data/teams.ts / src/data/stadiums.ts のマスタ。
-- 本ファイルは生成スクリプトで作成した (手で編集しないこと)。
-- 生成スクリプト: ~/workspace/new-game-log-port/generate-seed-sql.ts
--
-- (a) 前提
-- - マイグレーション 0001〜0009 が適用済みで、全テーブルが存在すること
-- (payment_splits は 0007、matches.revision は 0009 で追加)。
-- - Supabase の SQL Editor (postgres ロール) で実行すること (RLS をバイパスする)。
-- - 投入先ユーザーは public.authorized_users に登録済みの行から決める。
-- authorized_users が「ちょうど1件」でない場合、本ファイルは例外で停止する
-- (複数ユーザー環境では _seed_ctx への投入行を手で書き換えること)。
-- - マスタ (0004 / 0006) が適用済みでも再実行できるよう、マスタ投入は
-- すべて ON CONFLICT DO NOTHING で冪等にしてある。
--
-- (b) 実行順序 (本ファイルは単一トランザクション。エラー時は全体がロールバックする)
-- 1. 投入先 owner の確定 (_seed_ctx) と authorized_users 件数ガード
-- 2. マスタ投入 (categories / teams / stadiums / seat_types / stadium_seat_types)
-- ※ シードが参照する不足マスタ (後述) もここで先に追加する
-- 3. legacy_id → UUID の対応表 (_seed_map) を作る
-- matches.id は UUID 型のため、シード ID (excel_*) は legacy_id 列に保持し、
-- id は md5(owner_id || ':new-game-log:match:' || legacy_id) から決定的に生成する
-- (watch_records.id も同様に ':watch:' で生成。再実行しても同じ UUID になる)
-- 4. matches → watch_records → watch_record_categories / seats / tickets
-- → match_inning_scores / match_team_totals / match_pitchers / match_events
-- 5. 件数検証 (末尾の DO ブロック。不一致なら例外でロールバック) → commit
-- ※ matches.updated_at をシード値に保つため、投入中のみ
-- matches_set_updated_at トリガを無効化する (子テーブル挿入時の
-- revision 伝播トリガ (0009) が matches を UPDATE し、updated_at が
-- 現在時刻に化けるのを防ぐ)。revision 自体は伝播で 0 より大きくなるが、
-- これはアプリ経由の保存でも起こる通常の挙動であり、データ内容に影響しない。
--
-- (c) シード (seedData.ts) から2件の誤記を修正して投入する
-- 修正1: excel_jp_2026-02-28_12 (侍ジャパン vs 中日、2026-02-28)
-- 実結果 侍ジャパン 7-3 中日に合わせてスコアを 7-3 に修正した
-- (修正前は homeScore=3 / awayScore=7 と逆転していた)。
-- あわせて NPB公式ボックススコア
-- (https://npb.jp/bis/scores/japan/boxscore2026b_2.html) に基づく
-- イニング・安打・失策を追加した:
-- away (中日) = [1,0,1,1,0,0,0,0,0] / 安打7 / 失策1
-- home (侍ジャパン) = [1,1,0,0,5,0,0,0,0] / 安打9 / 失策0
-- (イニング合計は修正後スコア 3 / 7 と一致する)
-- 修正2: excel_d2_2026-08-30_18 (中日2軍、2026-08-30)
-- 対戦相手を阪神 (tigers) からハヤテベンチャーズ静岡 (hayate) に修正した。
-- スコア 12-2 は記録どおり正しいため不変。
-- イニングは検証可能な出典が無いため追加していない。
-- 同日の excel_d2_2026-08-30_19 は未確定のため修正していない (tigers のまま)。
-- ※ 'hayate' は src/data/teams.ts および 0004 に既存のため、マスタ追加は不要。
--
-- teams.ts の代表 ID (samurai_japan / team_australia 等) と
-- シード側 ID (japan_national / australia 等) は別 ID である。本 SQL は
-- 「シードが参照する ID で投入できる形」を優先し、シード側 ID を不足マスタ
-- として追加する (既存の samurai_japan 等の行とは別行として共存する)。
-- コード (teams.code) は一意制約があるため、既存の JPN / AUS と重ならない
-- 暫定値 JPN2 / AUS2 を付けた (表示名は日本語で 日本 / オーストラリア / チェコ)。
--
--
-- - yokohama / jingu / mazda の正式名称等は、stadiums.ts の既存マスタ
-- (yokohama_stadium / meiji_jingu / mazda_zoom_zoom) から確認できたため、
-- 同一施設の情報 (名称・略称・所在地・ホームチーム) を転記した (確認済み)。
-- - chatan の名称は指定どおり「北谷公園野球場」とした。ただし略称・所在地・
-- ホームチーム・ドーム区分は確認できる出典が無いため、略称は名称と同値、
-- 所在地とホームチームは NULL、ドーム区分は既定値 false とした (未確認)。
-- なおシード各行の stadiumCustom ('Agreスタジアム北谷') は
-- matches.stadium_custom_name にそのまま保持される。
-- - officialSeatTypes2026.ts の公式席種38件は「名称のみ・ID 無し」のため
-- seat_types へは投入しない。シードの席種名は seats.custom_seat_type_name
-- に保持される (シードに seatTypeId は存在しない)。
--
-- 次の3件は home_team_id = away_team_id (いずれも
-- tigers/tigers。オールスター / レジェンドゲームで、シード側が同一チームを
-- 両側に入れている) であり、DB の制約 matches_teams_distinct_ck
-- (home_team_id <> away_team_id) に違反するため、そのままでは投入できない。
-- データを推測で書き換えることはせず、本ファイル末尾にコメントアウトした
-- INSERT として残した。投入するには、対戦相手の確定 (例: 片側を other_team
-- にする等) か制約の見直しを別途判断すること。
-- excel_oth_2023-07-19_3 (2023-07-19 マイナビオールスターゲーム2023)
-- excel_oth_2024-07-25_7 (2024-07-25 DRAGONS CLASSIC LEGEND GAME2024)
-- excel_oth_2025-07-23_8 (2025-07-23 マイナビオールスターゲーム2025)
-- そのため本ファイルで投入される matches / watch_records は 256 件であり、
-- 末尾の件数検証も「投入分」の件数で照合する。
--
-- match_links (シードに links 無し)、payment_splits
-- (シードの costInfo.splits は全件空)、payments (分割払い明細の保存先は
-- payment_splits であり、payments に対応するシード項目は無い)、
-- import_batches / import_rows (取込管理用で投入対象外) は投入しない。
-- =====================================================================
begin;

-- 1. 投入先 owner の確定
create temp table _seed_ctx (owner_id uuid not null) on commit drop;
do $$
begin
if (select count(*) from public.authorized_users) <> 1 then
raise exception 'authorized_users must contain exactly 1 row to run this seed (found %)', (select count(*) from public.authorized_users);
end if;
end $$;
insert into _seed_ctx (owner_id) select user_id from public.authorized_users;

-- matches.updated_at をシード値に保つ (ヘッダ (b) 参照。commit 前に再有効化)
alter table public.matches disable trigger matches_set_updated_at;

-- 2. マスタ投入 (冪等)
