-- RPC 経由の保存では match_events に event_type='other' としても複写されるが、
-- 読み取り (toMatchRecord) では 'other' は復元対象外のため、本シードでは複写しない。

alter table public.matches enable trigger matches_set_updated_at;

-- 5. 件数検証 (投入分のみ。不一致なら例外で全体がロールバックする)
do $$
declare
v_owner uuid:= (select owner_id from _seed_ctx);
v_count bigint;
begin
select count(*) into v_count from public.matches where owner_id = v_owner and legacy_id like 'excel\_%';
if v_count <> 256 then raise exception 'matches count % <> 256', v_count; end if;
select count(*) into v_count from public.watch_records w join public.matches m on m.id = w.match_id where m.owner_id = v_owner and m.legacy_id like 'excel\_%';
if v_count <> 256 then raise exception 'watch_records count % <> 256', v_count; end if;
select count(*) into v_count from public.watch_record_categories c join public.matches m on m.id = (select match_id from public.watch_records where id = c.watch_record_id) where m.owner_id = v_owner and m.legacy_id like 'excel\_%';
if v_count <> 256 then raise exception 'watch_record_categories count % <> 256', v_count; end if;
select count(*) into v_count from public.seats s join public.watch_records w on w.id = s.watch_record_id join public.matches m on m.id = w.match_id where m.owner_id = v_owner and m.legacy_id like 'excel\_%';
if v_count <> 255 then raise exception 'seats count % <> 255', v_count; end if;
select count(*) into v_count from public.tickets t join public.matches m on m.id = t.match_id where m.owner_id = v_owner and m.legacy_id like 'excel\_%';
if v_count <> 256 then raise exception 'tickets count % <> 256', v_count; end if;
select count(*) into v_count from public.match_inning_scores i join public.matches m on m.id = i.match_id where m.owner_id = v_owner and m.legacy_id like 'excel\_%';
if v_count <> 18 then raise exception 'match_inning_scores count % <> 18', v_count; end if;
select count(*) into v_count from public.match_team_totals t join public.matches m on m.id = t.match_id where m.owner_id = v_owner and m.legacy_id like 'excel\_%';
if v_count <> 2 then raise exception 'match_team_totals count % <> 2', v_count; end if;
select count(*) into v_count from public.match_pitchers p join public.matches m on m.id = p.match_id where m.owner_id = v_owner and m.legacy_id like 'excel\_%';
if v_count <> 496 then raise exception 'match_pitchers count % <> 496', v_count; end if;
select count(*) into v_count from public.match_events e join public.matches m on m.id = e.match_id where m.owner_id = v_owner and m.legacy_id like 'excel\_%';
if v_count <> 144 then raise exception 'match_events count % <> 144', v_count; end if;
-- 誤記修正2件の期待値チェック
if not exists (select 1 from public.matches where owner_id = v_owner and legacy_id = 'excel_jp_2026-02-28_12' and home_score = 7 and away_score = 3) then
raise exception 'fix1 (excel_jp_2026-02-28_12 scores 7-3) not found'; end if;
if (select count(*) from public.match_inning_scores i join public.matches m on m.id = i.match_id where m.owner_id = v_owner and m.legacy_id = 'excel_jp_2026-02-28_12') <> 18 then
raise exception 'fix1 innings rows must be 18'; end if;
if not exists (select 1 from public.matches where owner_id = v_owner and legacy_id = 'excel_d2_2026-08-30_18' and away_team_id = 'hayate' and home_score = 12 and away_score = 2) then
raise exception 'fix2 (excel_d2_2026-08-30_18 away=hayate 12-2) not found'; end if;
end $$;

commit;

